 "/scoring":{eyebrow:"SCORING METHODOLOGY",title:"Consistent inputs. A transparent final score.",description:"AUPES follows the supplied Form E weighting model and keeps missing components pending rather than treating them as zero."},
 "/privacy":{eyebrow:"PRIVACY & CONFIDENTIALITY",title:"Evaluation data deserves careful handling.",description:"Access controls and aggregate instructor summaries are designed to keep evaluation information in the right hands."},
 "/contact":{eyebrow:"AUPES HELP",title:"Get help with access or evaluation tasks.",description:"Use this guide for account access, role assignment, missing evaluations and other AUPES workspace questions."},
 "/terms-of-use":{eyebrow:"RESPONSIBLE USE",title:"Use feedback to improve, not to harm.",description:"AUPES is intended for responsible academic evaluation and constructive professional development."}
