function InformationPage({route,navigate}:{route:string;navigate:(to:string)=>void}){
 const {t}=useAppSettings();
 const originalPage=PAGE_COPY[route]??PAGE_COPY["/about"];
 const page={eyebrow:t(originalPage.eyebrow),title:t(originalPage.title),description:t(originalPage.description)};
 const themes=[{title:"Agriculture & veterinary science",body:"Explore the role of agriculture, food systems, animal health and sustainable land use in teaching and applied research.",icon:<Sprout size={20}/>},{title:"Technology & innovation",body:"Build practical knowledge, engineering thinking and digital capability for a changing world.",icon:<Activity size={20}/>},{title:"Health & wellbeing",body:"Connect science, care, public health and better outcomes for individuals and communities.",icon:<ShieldCheck size={20}/>},{title:"Social sciences & humanities",body:"Study people, language, history, culture, institutions and social change.",icon:<BookMarked size={20}/>}];
 return <main className="container public-content internal-campus-page"><section className="public-page-heading"><div><small className="kicker">{page.eyebrow}</small><h1>{page.title}</h1><p>{page.description}</p></div><div className="page-heading-symbol"><span><GraduationCap size={30}/></span><small>{t("AUPES · AMBO")}</small><b>{t("Learning & discovery")}</b></div></section>
 {route==="/about"&&<><section className="public-section-grid about-lead"><article className="public-feature-panel"><span className="public-section-icon"><Building2 size={21}/></span><small className="kicker">{t("A PLACE TO LEARN AND CONTRIBUTE")}</small><h2>{t("Make evaluation a useful part of academic life.")}</h2><p>{t("Ambo University is a public academic community bringing together learners, educators and researchers. Its work spans teaching, professional learning, inquiry and engagement with communities.")}</p><p>{t("AUPES supports one important part of this mission: a clear, structured way to collect teaching feedback and turn it into insight for professional growth.")}</p><Button onClick={()=>navigate("/how-it-works")}>{t("How AUPES works")} <ArrowRight size={15}/></Button></article><aside className="university-facts"><small className="kicker">{t("OUR SHARED VALUES")}</small><div className="fact-line"><b>{t("Curiosity")}</b><span>{t("Ask questions, examine evidence and stay open to new ideas.")}</span></div><div className="fact-line"><b>{t("Responsibility")}</b><span>{t("Give feedback thoughtfully and respect the people behind the work.")}</span></div><div className="fact-line"><b>{t("Growth")}</b><span>{t("Use reflection to identify strengths and make progress over time.")}</span></div><PublicLink to="/academics" navigate={navigate} className="inline-link">{t("Explore academic life")} <ArrowRight size={14}/></PublicLink></aside></section><section className="public-three-cards"><article><span><BookOpen size={19}/></span><h3>{t("Teaching & learning")}</h3><p>{t("Support reflection on course delivery, learning experiences and instructional practice.")}</p></article><article><span><FlaskConical size={19}/></span><h3>{t("Research & innovation")}</h3><p>{t("Encourage inquiry, careful observation and practical solutions to real challenges.")}</p></article><article><span><Users size={19}/></span><h3>{t("Community engagement")}</h3><p>{t("Share knowledge and collaborate to strengthen the communities around us.")}</p></article></section></>}
 {route==="/academics"&&<><section className="academic-page-intro"><small className="kicker">{t("EXPLORE AREAS OF LEARNING")}</small><h2>{t("Knowledge takes many forms.")}</h2><p>{t("Academic fields connect theory with practice, local context with global ideas, and individual opportunity with collective progress.")}</p></section><section className="internal-academic-grid">{themes.map((theme,index)=><article key={theme.title} className="internal-academic-card"><span className="internal-academic-index">0{index+1}</span><span className="internal-academic-icon">{theme.icon}</span><h3>{t(theme.title)}</h3><p>{t(theme.body)}</p><PublicLink to="/research" navigate={navigate}>{t("Explore research connections")} <ArrowRight size={14}/></PublicLink></article>)}</section><section className="privacy-note"><span><BookOpen size={18}/></span><div><b>{t("Looking for evaluation forms?")}</b><p>{t("AUPES provides teaching-performance evaluation forms to authenticated users based on their assigned role.")}</p><PublicLink to="/sign-in" navigate={navigate} className="inline-link">{t("Sign in to your workspace")} <ArrowRight size={14}/></PublicLink></div></section></>}
 {route==="/research"&&<><section className="research-feature-grid"><article className="research-feature research-feature-main"><span><FlaskConical size={22}/></span><small className="kicker">{t("01 · DISCOVERY")}</small><h2>{t("Research begins with a better question.")}</h2><p>{t("Research culture depends on curiosity, evidence, collaboration and the willingness to learn from results. Academic inquiry can help explain problems and shape more useful approaches.")}</p></article><article className="research-feature"><span><Sprout size={22}/></span><small className="kicker">{t("02 · APPLIED KNOWLEDGE")}</small><h2>{t("Ideas that meet real needs.")}</h2><p>{t("Applied research connects technical and academic knowledge to agriculture, health, technology and community development.")}</p></article><article className="research-feature"><span><Users size={22}/></span><small className="kicker">{t("03 · SHARED IMPACT")}</small><h2>{t("Knowledge travels further together.")}</h2><p>{t("Partnerships help learning move between students, academic staff, institutions, industry and communities.")}</p></article></section><section className="research-bridge"><div><small className="kicker">{t("TEACHING AND DISCOVERY")}</small><h2>{t("Better teaching makes room for better questions.")}</h2><p>{t("Feedback and professional reflection can help educators understand what supports learning and where a new approach may help. AUPES is designed to organize that feedback within the academic process.")}</p></div><Button onClick={()=>navigate("/how-it-works")}>{t("Explore the evaluation process")} <ArrowRight size={15}/></Button></section></>}
 {route==="/news"&&<><section className="academic-page-intro"><small className="kicker">{t("EDITORIAL STORIES")}</small><h2>{t("People. Ideas. Progress.")}</h2><p>{t("A curated set of story themes for the AUPES website. These are not live news reports; they provide a starting point for future campus announcements and feature articles.")}</p></section><section className="internal-news-grid"><article><div className="internal-news-art internal-news-research"><FlaskConical size={27}/></div><small className="kicker">{t("RESEARCH & DISCOVERY")}</small><h3>{t("Questions that move knowledge forward")}</h3><p>{t("A look at how observation, experimentation and collaboration help turn curiosity into practical insight.")}</p><span className="news-status-tag">{t("Feature theme")}</span></article><article><div className="internal-news-art internal-news-community"><Users size={27}/></div><small className="kicker">{t("COMMUNITY & CULTURE")}</small><h3>{t("Learning beyond the classroom")}</h3><p>{t("Stories about knowledge-sharing, cultural life, service and the connections between the university and its wider community.")}</p><span className="news-status-tag">{t("Feature theme")}</span></article><article><div className="internal-news-art internal-news-teaching"><GraduationCap size={27}/></div><small className="kicker">{t("TEACHING & GROWTH")}</small><h3>{t("Small improvements, lasting impact")}</h3><p>{t("Explore how reflection, constructive feedback and professional learning can strengthen teaching over time.")}</p><span className="news-status-tag">{t("Feature theme")}</span></article></section></>}
 {route==="/how-it-works"&&<><section className="steps-grid">{[{n:"01",title:"An administrator sets the cycle",body:"Authorized staff create accounts and assign the appropriate form, course, instructor, academic term and due date."},{n:"02",title:"Evaluators complete assigned forms",body:"Participants sign in and respond to the questions for their role. A rating of NA can be used when an item does not apply."},{n:"03",title:"Responses are validated and summarized",body:"The system checks that the task is assigned to the current user and collects the submitted ratings for aggregation."},{n:"04",title:"Authorized users review results",body:"Users see the result summaries permitted for their account. A final weighted score remains pending until every required component is available."}].map(item=><article key={item.n}><span className="step-num">{item.n}</span><div><h3>{t(item.title)}</h3><p>{t(item.body)}</p></div></article>)}</section><section className="forms-overview"><div className="section-heading-inline"><div><small className="kicker">{t("FOUR PERSPECTIVES")}</small><h2>{t("Each form has a distinct role.")}</h2></div><PublicLink to="/scoring" navigate={navigate} className="inline-link">{t("View weights")} <ArrowRight size={14}/></PublicLink></div><div className="form-perspective-grid">{FORMS.map(form=><article key={form}><div><span className={"form-tag form-"+form}>{t(FORM_META[form].shortLabel)}</span><b>{FORM_META[form].weight}%</b></div><h3>{t(FORM_META[form].label)}</h3><p>{t(FORM_META[form].description)}</p></article>)}</div></section></>}
 {route==="/scoring"&&<><section className="scoring-layout"><article className="scoring-main-card"><small className="kicker">{t("FORM E WEIGHTING MODEL")}</small><h2>{t("How the total is calculated")}</h2><p>{t("Each component average is converted to a percentage of its own evaluator weight. The four weighted contributions are then added.")}</p><div className="formula-card"><span>{t("Component contribution")}</span><strong>(Average rating ÷ 5) × component weight</strong></div><div className="formula-card formula-total"><span>{t("Final result")}</span><strong>{t("Student + Department head + Peer + Self")}</strong></div><p className="scoring-note"><ShieldCheck size={15}/> {t("A final score is shown only when all four component averages are available.")}</p></article><aside className="scoring-weight-list"><small className="kicker">{t("WEIGHT DISTRIBUTION")}</small>{FORMS.map(form=><div className="scoring-weight-row" key={form}><span className={"form-tag form-"+form}>{t(FORM_META[form].shortLabel)}</span><div><b>{t(FORM_META[form].label)}</b><div className="track"><i style={{width:FORM_META[form].weight+"%"}}/></div></div><strong>{FORM_META[form].weight}%</strong></div>)}</aside></section><section className="public-three-cards"><article><span><CheckCircle2 size={19}/></span><h3>{t("NA is not a score")}</h3><p>{t("Not-applicable ratings are excluded from the component average; a valid zero remains a score.")}</p></article><article><span><Scale size={19}/></span><h3>{t("Weights are applied once")}</h3><p>{t("Focus-area averages help explain a result and do not add extra weights to the total.")}</p></article><article><span><Clock3 size={19}/></span><h3>{t("Missing means pending")}</h3><p>{t("A missing component is not silently replaced with zero.")}</p></article></section></>}
 {route==="/privacy"&&<><section className="privacy-grid"><article><span><LockKeyhole size={20}/></span><h3>{t("Role-based access")}</h3><p>{t("The workspace uses authenticated accounts and role permissions. Evaluators are expected to complete only the assignments available to them.")}</p></article><article><span><Users size={20}/></span><h3>{t("Aggregate instructor summaries")}</h3><p>{t("Individual student identities are excluded from instructor-facing result summaries; the summaries focus on aggregated ratings and feedback.")}</p></article><article><span><ShieldCheck size={20}/></span><h3>{t("Administrator-managed accounts")}</h3><p>{t("There is no public self-registration. Accounts are provisioned by AUPES administrators, so access can be managed by institutional role.")}</p></article></section><section className="privacy-note"><span><CircleHelp size={18}/></span><div><b>{t("Need access help or think something is wrong?")}</b><p>{t("Contact your department AUPES administrator. Avoid sharing passwords, private evaluation responses or student information through public channels.")}</p><PublicLink to="/contact" navigate={navigate} className="inline-link">{t("Contact & support")} <ArrowRight size={14}/></PublicLink></div></section></>}
 {route==="/contact"&&<section className="contact-grid"><article className="contact-card contact-card-primary"><span><CircleHelp size={21}/></span><small className="kicker">{t("AUPES WORKSPACE SUPPORT")}</small><h2>{t("Start with your department administrator.")}</h2><p>{t("Your department or system administrator is the right first contact for account activation, role assignment, missing evaluations and course-assignment questions.")}</p><Button onClick={()=>navigate("/sign-in")}>{t("Go to sign in")} <ArrowRight size={15}/></Button></article><article className="contact-card"><span><Mail size={20}/></span><small className="kicker">{t("ACCOUNT ACCESS")}</small><h2>{t("Can't sign in?")}</h2><p>{t("Use the password recovery option on the sign-in page. If your account is not active or your profile is missing, contact the AUPES administrator for help.")}</p><PublicLink className="inline-link" to="/sign-in" navigate={navigate}>{t("Open sign-in page")} <ArrowRight size={14}/></PublicLink></article><article className="contact-card"><span><ClipboardCheck size={20}/></span><small className="kicker">{t("EVALUATION TASKS")}</small><h2>{t("Missing an assignment?")}</h2><p>{t("Assignments are added by an administrator and appear in your workspace according to your assigned role. Ask your department administrator to review the assignment.")}</p><PublicLink className="inline-link" to="/how-it-works" navigate={navigate}>{t("Read how AUPES works")} <ArrowRight size={14}/></PublicLink></article></section>}
 {route==="/terms-of-use"&&<section className="terms-content"><article><h2>{t("Use AUPES constructively")}</h2><p>{t("Evaluation responses should be honest, relevant to the course and respectful of the people being evaluated. Do not use the system to harass, threaten or submit knowingly false information.")}</p></article><article><h2>{t("Protect account access")}</h2><p>{t("Keep your password private, use only your own account and contact an administrator if you suspect unauthorized access. Do not attempt to access another user's assignments or results.")}</p></article><article><h2>{t("Handle evaluation information responsibly")}</h2><p>{t("Do not share evaluation responses, reports or personal information outside the authorized academic process. The information available to each user depends on their role and permissions.")}</p></article><article><h2>{t("Use is subject to institutional procedures")}</h2><p>{t("AUPES supports the evaluation workflow and does not replace official policies, academic regulations or formal review procedures.")}</p></article><p className="terms-disclaimer">{t("This page summarizes expected platform use; it is not legal advice or a substitute for official regulations.")}</p></section>}
 </main>;
}
function LoginPage({navigate}:{navigate:(to:string)=>void}){
 const {t}=useAppSettings();
 const [email,setEmail]=useState("");const [password,setPassword]=useState("");const [reset,setReset]=useState(false);const [busy,setBusy]=useState(false);const [notice,setNotice]=useState<Notice>(null);
 async function submit(e:FormEvent){e.preventDefault();setBusy(true);setNotice(null);try{if(reset){const {error}=await supabase.auth.resetPasswordForEmail(email.trim(),{redirectTo:window.location.origin+"/sign-in"});if(error)throw error;setNotice({type:"success",text:"If this account exists, password reset instructions have been sent."});}else{const {error}=await supabase.auth.signInWithPassword({email:email.trim(),password});if(error)throw error;navigate("/app/workspace");}}catch(err){setNotice({type:"error",text:err instanceof Error?err.message:"Unable to sign in."});}finally{setBusy(false);}}
 return <div className="auth-page"><main className="container auth-layout"><section className="auth-form-panel"><small className="kicker">{t(reset?"ACCOUNT RECOVERY":"YOUR UNIVERSITY WORKSPACE")}</small><h1>{t(reset?"Reset your password.":"Welcome back.")}</h1><p className="auth-lead">{t(reset?"Enter your university email to receive password-reset instructions.":"Sign in with the account provided by your AUPES administrator.")}</p><form onSubmit={submit} className="form-stack auth-form"><label>{t("Email address")}<input type="email" autoComplete="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@university.edu.et"/></label>{!reset&&<label>{t("Password")}<input type="password" autoComplete="current-password" required value={password} onChange={e=>setPassword(e.target.value)} placeholder={t("Enter your password")}/></label>}<Notice notice={notice}/><Button type="submit" disabled={busy} className="btn-lg full">{busy?<LoaderCircle size={17} className="spin"/>:<LockKeyhole size={17}/>} {busy?t("Please wait…"):reset?t("Send reset link"):t("Sign in")} <ArrowRight size={16}/></Button></form><button className="text-btn reset-btn" onClick={()=>{setReset(!reset);setNotice(null)}}>{reset?t("Return to sign in"):t("Forgot your password?")}</button><div className="login-note"><ShieldCheck size={16}/><span>{t("Accounts are provisioned by AUPES administrators. There is no public self-registration.")}</span></div><PublicLink to="/" navigate={navigate} className="auth-home-link">← {t("Back to the public site")}</PublicLink></section><aside className="auth-story"><div className="auth-story-mark"><img src="/images/logo.png" alt={t("Ambo University logo")} onError={e=>{e.currentTarget.style.display="none"}}/></div><small className="kicker">{t("AMBO UNIVERSITY · AUPES")}</small><h2>{t("Better teaching begins with honest feedback.")}</h2><p>{t("Return to your assigned evaluations, submit thoughtful feedback and review the insights available to your role.")}</p><div className="auth-story-points"><span><CheckCircle2 size={16}/> {t("Structured evaluation forms")}</span><span><CheckCircle2 size={16}/> {t("Defined scoring weights")}</span><span><CheckCircle2 size={16}/> {t("Role-aware access to results")}</span></div><div className="auth-story-foot"><GraduationCap size={18}/><span>{t("Academic quality is built one useful insight at a time.")}</span></div></aside></main></div>;
}
type PublicAIMessage = { role: "user" | "model"; content: string };

function PublicAIAssistant() {
 const [open,setOpen]=useState(false);
 const [draft,setDraft]=useState("");
 const [messages,setMessages]=useState<PublicAIMessage[]>([]);
 const [busy,setBusy]=useState(false);
 const [error,setError]=useState("");
 const endRef=useRef<HTMLDivElement|null>(null);
 const inputRef=useRef<HTMLTextAreaElement|null>(null);
 useEffect(()=>{if(open){endRef.current?.scrollIntoView({behavior:"smooth",block:"end"});const timer=window.setTimeout(()=>inputRef.current?.focus(),120);return()=>window.clearTimeout(timer)}},[open,messages,busy]);
 async function send(question?:string){
  const content=(question??draft).trim();
  if(!content||busy)return;
  const next=[...messages,{role:"user" as const,content}];
  setMessages(next);setDraft("");setError("");setBusy(true);
  try{
   const {data,error:invokeError}=await supabase.functions.invoke("public-ai-assistant",{body:{messages:next.map(({role,content})=>({role,content}))}});
   if(invokeError)throw invokeError;
   if(data?.error)throw new Error(String(data.error));
   if(typeof data?.answer!=="string"||!data.answer.trim())throw new Error("I couldn't answer just now. Please try again.");
   setMessages([...next,{role:"model",content:data.answer.trim()}]);
  }catch(err){
   setError(err instanceof Error?err.message:"The assistant is temporarily unavailable. Please try again.");
  }finally{setBusy(false)}
 }
 const suggestions=["How does AUPES work?","How are evaluation scores calculated?","How can I get an account?"];
 return <div className="ai-assistant-root">
  {open&&<section className="ai-assistant-card" role="dialog" aria-label="AUPES AI assistant" aria-modal="false">
   <header className="ai-assistant-header">
    <span className="ai-assistant-mark"><Bot size={21}/></span>
    <div className="ai-assistant-heading"><strong>AUPES assistant</strong><small><i className="ai-assistant-online"/> Here to help with the portal</small></div>
    <button type="button" className="ai-assistant-close" aria-label="Close assistant" onClick={()=>setOpen(false)}><X size={17}/></button>
   </header>
   <div className="ai-assistant-messages" aria-live="polite">
    {!messages.length&&<div className="ai-assistant-welcome">
     <span className="ai-assistant-eyebrow">AI HELP DESK</span><h3>Hi there. What can I help you with?</h3>
     <p>Ask about AUPES, evaluation forms, scoring, or getting access to the portal.</p>
     <div className="ai-assistant-suggestions">{suggestions.map(item=><button type="button" key={item} onClick={()=>void send(item)} disabled={busy}>{item}</button>)}</div>
    </div>}
    {messages.map((message,index)=><div key={index} className={"ai-assistant-message "+(message.role==="user"?"user":"assistant")}>
     {message.role==="model"&&<span className="ai-assistant-avatar"><Sparkles size={13}/></span>}
     <div className="ai-assistant-bubble">{message.content}</div>
    </div>)}
    {busy&&<div className="ai-assistant-typing"><span className="ai-assistant-avatar"><Sparkles size={13}/></span><span>Thinking</span><span className="ai-assistant-typing-dots"><i/><i/><i/></span></div>}
    {error&&<div className="ai-assistant-message assistant ai-assistant-error"><span className="ai-assistant-avatar"><CircleHelp size={13}/></span><div className="ai-assistant-bubble">{error}</div></div>}
    <div ref={endRef}/>
   </div>
   <form className="ai-assistant-form" onSubmit={event=>{event.preventDefault();void send()}}>
    <div className="ai-assistant-input-wrap"><textarea ref={inputRef} className="ai-assistant-input" rows={1} maxLength={1200} value={draft} onChange={event=>setDraft(event.target.value)} onKeyDown={event=>{if(event.key==="Enter"&&!event.shiftKey){event.preventDefault();void send()}}} placeholder="Ask a question…" aria-label="Your question" disabled={busy}/>
     <button className="ai-assistant-send" type="submit" disabled={busy||!draft.trim()} aria-label="Send message">{busy?<LoaderCircle className="spin" size={16}/>:<Send size={16}/>}</button>
    </div>
    <div className="ai-assistant-footnote"><span>AI answers can make mistakes.</span><button type="button" className="ai-assistant-reset" onClick={()=>{setMessages([]);setDraft("");setError("");inputRef.current?.focus()}}>New chat</button></div>
   </form>
  </section>}
  <button type="button" className="ai-assistant-launcher" onClick={()=>setOpen(value=>!value)} aria-label={open?"Close AUPES assistant":"Open AUPES AI assistant"} aria-expanded={open}>
   {open?<X size={21}/>:<><MessageCircle size={21}/><span className="ai-assistant-launcher-label">Ask AI</span><Sparkles className="ai-assistant-launcher-sparkle" size={11}/></>}
  </button>
 </div>;
}

function PublicSite({route,navigate}:{route:string;navigate:(to:string)=>void}){const {t}=useAppSettings();
 const pageTitle=route==="/"?"AUPES · Ambo University Performance Evaluation System":route==="/sign-in"||route==="/workspace"?"Sign in · AUPES":(PAGE_COPY[route]?.title?PAGE_COPY[route].title+" · AUPES":"Page not found · AUPES");
 useEffect(()=>{document.title=pageTitle},[pageTitle]);
 if(route==="/sign-in"||route==="/workspace")return <><LoginPage navigate={navigate}/><PublicAIAssistant/></>;
 const known=["/","/about","/academics","/research","/news","/how-it-works","/scoring","/privacy","/contact","/terms-of-use"];
 return <><div className="landing public-site"><PublicHeader route={route} navigate={navigate}/>{route==="/" ? <LandingHome navigate={navigate}/>:known.includes(route)?<InformationPage route={route} navigate={navigate}/>:<main className="container public-not-found"><small className="kicker">{t("PAGE NOT FOUND")}</small><h1>{t("We couldn’t find that page.")}</h1><p>{t("The address may have changed, or the page may no longer exist.")}</p><Button onClick={()=>navigate("/")}>{t("Return home")} <ArrowRight size={15}/></Button></main>}<PublicFooter navigate={navigate}/></div><PublicAIAssistant/></>;
}

function Stat({label,value,detail,icon:Icon,tone="green"}:{label:string;value:string|number;detail:string;icon:typeof Users;tone?:string}){const {t}=useAppSettings();return <article className="stat"><span className={"stat-icon tone-"+tone}><Icon size={19}/></span><span className="stat-label">{t(label)}</span><strong>{value}</strong><small>{t(detail)}</small></article>}
function Empty({icon:Icon=FileText,title,detail}:{icon?:typeof FileText;title:string;detail:string}){const {t}=useAppSettings();return <div className="empty"><span><Icon size={24}/></span><h3>{t(title)}</h3><p>{t(detail)}</p></div>}
function Modal({title,description,onClose,children}:{title:string;description:string;onClose:()=>void;children:React.ReactNode}){const {t}=useAppSettings();return <div className="overlay modal-overlay" role="dialog" aria-modal="true"><button className="scrim" onClick={onClose} aria-label={t("Close modal")}/><section className="modal"><header><div><small className="kicker">{t("AUPES ADMINISTRATION")}</small><h2>{t(title)}</h2><p>{t(description)}</p></div><button className="close-btn" onClick={onClose} aria-label={t("Close")}><X size={19}/></button></header>{children}</section></div>}

function EvaluationForm({assignment,onCancel,onSubmitted}:{assignment:Assignment;onCancel:()=>void;onSubmitted:()=>void}){const {t}=useAppSettings();
 const questions=FORM_QUESTIONS[assignment.form_type] as Question[];const [answers,setAnswers]=useState<Record<string,Rating>>({});const [rationales,setRationales]=useState<Record<string,string>>({});const [strengths,setStrengths]=useState("");const [improvements,setImprovements]=useState("");const [busy,setBusy]=useState(false);const [notice,setNotice]=useState<Notice>(null);
 const groups=useMemo(()=>questions.reduce<Record<string,Question[]>>((a,q)=>{(a[q.area]??=[]).push(q);return a;},{}),[questions]);
 const answered=questions.filter(q=>answers[q.id]!==undefined).length;const percent=Math.round(answered/questions.length*100);
 async function submit(e:FormEvent){e.preventDefault();if(answered!==questions.length)return;setBusy(true);setNotice(null);try{const {error}=await supabase.rpc("submit_evaluation",{p_assignment_id:assignment.id,p_answers:answers,p_rationales:rationales,p_strengths:strengths,p_improvements:improvements});if(error)throw error;onSubmitted();}catch(err){setNotice({type:"error",text:err instanceof Error?err.message:"Unable to submit your evaluation."});}finally{setBusy(false);}}
 return <div className="page-stack form-page"><div className="back-row"><button className="text-btn" onClick={onCancel}>{t("← Back to evaluations")}</button><span><ShieldCheck size={15}/> {t("Secure evaluation")}</span></div><div className="form-hero"><div><span className={"form-tag form-"+assignment.form_type}>{formCode(assignment.form_type)}</span><span className="form-weight">{FORM_META[assignment.form_type].weight}% {t("Evaluator weight")}</span><h1>{t(formLabel(assignment.form_type))}</h1><p>{t(FORM_META[assignment.form_type].description)}. {t("Rate every item and choose NA whenever it is not applicable.")}</p></div><div className="form-progress"><span>{t("Completion")}</span><strong>{percent}%</strong><div className="track"><i style={{width:percent+"%"}}/></div><small>{answered}/{questions.length} {t("items answered")}</small></div></div>
 <div className="course-context"><span className="context-icon"><BookOpen size={20}/></span><div><small>{t("COURSE UNDER EVALUATION")}</small><strong>{assignment.course_title}</strong><span>{assignment.course_code} · {assignment.academic_year} · {t("Semester")} {assignment.semester}{assignment.batch?" · "+t("Batch")+" "+assignment.batch:""}</span></div><div className="context-teacher"><small>{t("INSTRUCTOR")}</small><strong>{assignment.instructor?.full_name||t("Assigned instructor")}</strong><span>{assignment.instructor?.department||t("Department")}</span></div></div>
 <form onSubmit={submit} className="questionnaire"><div className="rating-guide"><div><strong>{t("Rating scale")}</strong><span>{t("5 Excellent · 4 Very good · 3 Good · 2 Fair · 1 Poor · 0 Very poor")}</span></div><b>{t("NA = Not applicable")}</b></div>
 {Object.entries(groups).map(([area,items],index)=><section className="question-group" key={area}><header><span className="group-num">{String(index+1).padStart(2,"0")}</span><div><h2>{t(area)}</h2><small>{items.length} {t("evaluation items")}</small></div><span className="group-progress">{items.filter(q=>answers[q.id]!==undefined).length}/{items.length}</span></header>{items.map(q=><div className="question-row" key={q.id}><div className="question-copy"><span>{q.order}.</span><p>{t(q.prompt)}</p></div><div className="rating-options" role="radiogroup" aria-label={t(q.prompt)}>{RATINGS.map(value=><button type="button" role="radio" aria-checked={answers[q.id]===value} key={String(value)} className={cx("rating",value==="NA"&&"rating-na",answers[q.id]===value&&"selected",answers[q.id]===value&&value===5&&"best",answers[q.id]===value&&value===0&&"low")} onClick={()=>setAnswers(old=>({...old,[q.id]:value}))}>{value}</button>)}</div><label className="rating-reason"><span>{t("Why did you choose this rating?")} <small>{t("Optional")}</small></span><textarea rows={2} maxLength={500} value={rationales[q.id]??""} onChange={e=>setRationales(old=>({...old,[q.id]:e.target.value}))} placeholder={t("Share a brief example or reason…")}/></label></div>)}</section>)}
 <section className="question-group"><header><span className="group-num"><Sparkles size={16}/></span><div><h2>{t("Written feedback")}</h2><small>{t("Optional, but valuable for professional growth")}</small></div></header><div className="feedback-grid"><label>{t("Appreciable strengths")}<textarea rows={4} value={strengths} onChange={e=>setStrengths(e.target.value)} placeholder={t("What is this instructor doing particularly well?")}/></label><label>{t("Suggested points to improve")}<textarea rows={4} value={improvements} onChange={e=>setImprovements(e.target.value)} placeholder={t("What could help improve teaching and learning?")}/></label></div></section>
 <Notice notice={notice}/><div className="submit-bar"><div><strong>{answered===questions.length?t("Ready to submit"):t("Complete all rating items")}</strong><span>{answered===questions.length?t("Review your ratings before submitting."):t("Choose NA if an item does not apply.")}</span></div><Button type="submit" disabled={busy||answered!==questions.length} className="btn-lg">{busy?<LoaderCircle size={17} className="spin"/>:<CheckCircle2 size={17}/>} {busy?t("Submitting…"):t("Submit evaluation")} <ArrowRight size={16}/></Button></div></form></div>;
}

function AppShell({session,profile,onSignOut}:{session:Session;profile:Profile;onSignOut:()=>void}){
 const {t}=useAppSettings();
 const [page,setPage]=useState<Page>(()=>resolveWorkspaceRoute(window.location.pathname).page);
 const [mobileNav,setMobileNav]=useState(false);
 const [assignments,setAssignments]=useState<Assignment[]>([]);
 const [people,setPeople]=useState<Profile[]>([]);
 const [summaries,setSummaries]=useState<SummaryRow[]>([]);
 const [busy,setBusy]=useState(true);
 const [notice,setNotice]=useState<Notice>(null);
 const [refreshToken,setRefreshToken]=useState(0);
 const [activeAssignment,setActiveAssignment]=useState<Assignment|null>(null);
 const [userModal,setUserModal]=useState(false);
 const [assignmentModal,setAssignmentModal]=useState(false);
 const admin=profile.role==="admin";
 const refresh=()=>setRefreshToken(v=>v+1);
 const navigate=(next:Page,assignment?:Assignment)=>{
  const nextAssignment=assignment??activeAssignment;
  if(next==="fill"&&!nextAssignment){setNotice({type:"error",text:"Open an available evaluation before navigating to the form."});return;}
  setPage(next);setMobileNav(false);setNotice(null);
  if(next==="fill")setActiveAssignment(nextAssignment);else setActiveAssignment(null);
  const nextPath=next==="overview"?WORKSPACE_ROOT:next==="fill"?WORKSPACE_ROOT+"/evaluate/"+nextAssignment!.id:WORKSPACE_ROOT+"/"+next;
  if(window.location.pathname!==nextPath)window.history.pushState({},"",nextPath);
  window.scrollTo({top:0,behavior:"auto"});
 };
 useEffect(()=>{let alive=true;async function load(){setBusy(true);try{
  const a=await supabase.from("evaluation_assignments").select("*, instructor:profiles!evaluation_assignments_instructor_id_fkey(full_name,department,college), evaluator:profiles!evaluation_assignments_evaluator_id_fkey(full_name,role)").order("created_at",{ascending:false});
  if(a.error)throw a.error;if(alive)setAssignments((a.data??[]) as Assignment[]);
  const s=await supabase.from("evaluation_summaries").select("*");if(s.error)throw s.error;if(alive)setSummaries((s.data??[]) as SummaryRow[]);
  if(admin){const p=await supabase.from("profiles").select("id,full_name,email,role,department,college,is_active").order("full_name");if(p.error)throw p.error;if(alive)setPeople((p.data??[]) as Profile[]);}
 }catch(err){if(alive)setNotice({type:"error",text:err instanceof Error?t(err.message):t("Some workspace data could not be loaded.")});}finally{if(alive)setBusy(false);}}
 void load();return()=>{alive=false};
 },[session.user.id,profile.id,profile.role,admin,refreshToken]);
 useEffect(()=>{
  const sync=()=>{const route=resolveWorkspaceRoute(window.location.pathname);setPage(route.page);setMobileNav(false);
   if(route.assignmentId){setActiveAssignment(assignments.find(a=>a.id===route.assignmentId&&a.evaluator_id===session.user.id&&a.status==="open")??null);}
   else if(route.page!=="fill")setActiveAssignment(null);
  };
  window.addEventListener("popstate",sync);sync();return()=>window.removeEventListener("popstate",sync);
 },[assignments,session.user.id]);
 useEffect(()=>{
  const route=resolveWorkspaceRoute(window.location.pathname);
  const disallowed=((page==="accounts"||page==="assignments")&&!admin)||(page==="evaluations"&&admin);
  if(disallowed){setPage("overview");setActiveAssignment(null);if(window.location.pathname!==WORKSPACE_ROOT)window.history.replaceState({},"",WORKSPACE_ROOT);setNotice({type:"info",text:"That page is not available for your account role."});return;}
  if(page==="fill"&&!busy){
   const match=assignments.find(a=>a.id===route.assignmentId&&a.evaluator_id===session.user.id&&a.status==="open");
   if(match)setActiveAssignment(match);
   else{setPage("overview");setActiveAssignment(null);if(window.location.pathname!==WORKSPACE_ROOT)window.history.replaceState({},"",WORKSPACE_ROOT);setNotice({type:"info",text:"This evaluation is unavailable, already submitted, or not assigned to your account."});}
  }
 },[page,admin,profile.role,assignments,busy,session.user.id]);
 const mine=assignments.filter(a=>a.evaluator_id===session.user.id);
 const open=mine.filter(a=>a.status==="open");
 const nav=[
  {id:"overview" as Page,label:t("Overview"),icon:LayoutDashboard},
  {id:"evaluations" as Page,label:t("My evaluations"),icon:ClipboardCheck,hide:admin},
  {id:"results" as Page,label:t("Performance results"),icon:ChartNoAxesCombined},
  {id:"assignments" as Page,label:t("Evaluation assignments"),icon:CalendarDays,hide:!admin},
  {id:"accounts" as Page,label:t("Account management"),icon:Users,hide:!admin}
 ].filter(item=>!item.hide);
 function complete(){setActiveAssignment(null);navigate("evaluations");setNotice({type:"success",text:"Evaluation submitted successfully. Thank you for contributing to teaching quality."});refresh();}
 return <div className="app-shell workspace-shell">
  {mobileNav&&<button className="mobile-scrim" aria-label={t("Close navigation")} onClick={()=>setMobileNav(false)}/>}
  <aside className={cx("sidebar","workspace-sidebar",mobileNav&&"sidebar-open")}>
   <div className="workspace-sidebar-heading"><span className="workspace-status-dot"/><span>{t("Workspace")}</span></div>
   <nav className="side-nav workspace-side-nav" aria-label={t("Workspace navigation")}>
    {nav.map(item=>{const Icon=item.icon;return <button key={item.id} type="button" title={item.label} aria-label={item.label} aria-current={page===item.id?"page":undefined} className={cx("side-link","workspace-side-link",page===item.id&&"side-link-active")} onClick={()=>navigate(item.id)}>
     <span className="workspace-link-icon"><Icon size={18}/></span><span className="side-link-label">{item.label}</span>{item.id==="evaluations"&&open.length>0&&<b className="side-link-count">{open.length}</b>}
    </button>})}
   </nav>
   <div className="sidebar-bottom workspace-sidebar-bottom"><div className="sidebar-user workspace-profile-row">
    <Avatar name={profile.full_name||profile.email}/><div className="workspace-profile-copy"><b>{profile.full_name||profile.email}</b><small>{t(roleLabel(profile.role))}</small></div>
    <button className="icon-btn workspace-signout" type="button" title={t("Sign out")} aria-label={t("Sign out")} onClick={onSignOut}><LogOut size={17}/></button>
   </div></div>
   <button className="icon-btn close-side" type="button" onClick={()=>setMobileNav(false)} aria-label={t("Close navigation")}><X size={18}/></button>
  </aside>
  <div className="main-area workspace-main">
   <header className="topbar workspace-topbar"><div className="topbar-left"><button className="icon-btn mobile-menu" type="button" onClick={()=>setMobileNav(true)} aria-label={t("Open navigation")}><Menu size={20}/></button><span className="workspace-topbar-label">{t("Workspace")}</span></div>
    <div className="topbar-right"><span className="workspace-role-chip">{admin?<ShieldCheck size={15}/>:<UserRound size={15}/>}<span>{t(roleLabel(profile.role))}</span></span><AppSettingsMenu workspace/></div>
   </header>
   <main className="content-area workspace-content"><Notice notice={notice} onClose={()=>setNotice(null)}/>
    {page==="overview"&&<Dashboard profile={profile} mine={mine} assignments={assignments} people={people} summaries={summaries} admin={admin} busy={busy} navigate={navigate} start={a=>navigate("fill",a)} onUser={()=>setUserModal(true)} onAssignment={()=>setAssignmentModal(true)}/>}
    {page==="evaluations"&&!admin&&<EvaluationList assignments={mine} busy={busy} start={a=>navigate("fill",a)}/>}
    {page==="results"&&<ResultsPage summaries={summaries} people={people} profile={profile} admin={admin}/>}
    {page==="accounts"&&admin&&<AccountsPage people={people} busy={busy} onCreate={()=>setUserModal(true)}/>}
    {page==="assignments"&&admin&&<AssignmentsPage assignments={assignments} busy={busy} onCreate={()=>setAssignmentModal(true)}/>}
    {page==="fill"&&activeAssignment&&<EvaluationForm assignment={activeAssignment} onCancel={()=>navigate("evaluations")} onSubmitted={complete}/>}
   </main>
   <footer className="app-footer workspace-footer"><span>{t("Academic evaluation workspace")}</span><span><ShieldCheck size={14}/> {t("Secure academic evaluation")}</span></footer>
  </div>
  {userModal&&<CreateUserModal session={session} onClose={()=>setUserModal(false)} onCreated={message=>{setUserModal(false);setNotice({type:"success",text:message});refresh()}}/>}
  {assignmentModal&&<CreateAssignmentModal people={people} admin={profile} onClose={()=>setAssignmentModal(false)} onCreated={message=>{setAssignmentModal(false);setNotice({type:"success",text:message});refresh()}}/>}
 </div>;
}

function Dashboard({profile,mine,assignments,people,summaries,admin,busy,navigate,start,onUser,onAssignment}:{profile:Profile;mine:Assignment[];assignments:Assignment[];people:Profile[];summaries:SummaryRow[];admin:boolean;busy:boolean;navigate:(page:Page)=>void;start:(a:Assignment)=>void;onUser:()=>void;onAssignment:()=>void}){
 const {t}=useAppSettings();
 const open=mine.filter(a=>a.status==="open");const done=mine.filter(a=>a.status==="submitted");
 const aggregate=useMemo(()=>[...new Set(summaries.map(r=>r.instructor_id))].map(id=>{const rows=summaries.filter(r=>r.instructor_id===id);return {id,rows,person:people.find(p=>p.id===id),score:finalWeightedScore(rows)}}).sort((a,b)=>(b.score??-1)-(a.score??-1)),[summaries,people]);
 const firstName=profile.full_name.trim().split(/\s+/)[0];
 const title=admin?t("Evaluation overview"):profile.role==="instructor"?t("Performance snapshot"):firstName?t("Your evaluation tasks")+", "+firstName:t("Your evaluation tasks");
 const myRows=summaries.filter(r=>r.instructor_id===profile.id);const final=finalWeightedScore(myRows);
 return <div className="page-stack"><section className="welcome-row"><div><small className="kicker"><i/> {t("WORKSPACE SNAPSHOT")}</small><h1>{title}</h1><p>{admin?t("Monitor responses, manage accounts and keep evaluation cycles moving."):profile.role==="instructor"?t("Review your weighted result and the feedback supporting it."):t("Find your open forms and contribute to a fair teaching review.")}</p></div><div className="welcome-actions">{admin?<><Button variant="outline" onClick={onUser}><Plus size={16}/> {t("Add account")}</Button><Button onClick={onAssignment}><ClipboardCheck size={16}/> {t("Assign evaluation")}</Button></>:profile.role!=="instructor"&&<Button onClick={()=>navigate("evaluations")}>{t("Open my evaluations")} <ArrowRight size={16}/></Button>}</div></section>
 <div className="stats-grid"><Stat label={t(admin?"Registered accounts":"Assigned evaluations")} value={busy?"—":admin?people.length:mine.length} detail={t(admin?"Across university roles":"For your account")} icon={admin?Users:FileText}/><Stat label={t(admin?"Open assignments":"Awaiting completion")} value={busy?"—":admin?assignments.filter(a=>a.status==="open").length:open.length} detail={t(admin?"Waiting for responses":open.length?"Keep the cycle moving":"You’re all caught up")} icon={Clock3} tone="gold"/><Stat label={t(admin?"Submitted evaluations":"Completed")} value={busy?"—":admin?assignments.filter(a=>a.status==="submitted").length:done.length} detail={t("Submitted successfully")} icon={CheckCircle2} tone="blue"/><Stat label={t(admin?"Instructors with results":"Final result")} value={busy?"—":admin?aggregate.length:final===null?t("Pending"):final.toFixed(1)+"%"} detail={t(admin?"Summary data available":"Weighted score out of 100")} icon={Award} tone="purple"/></div>
 <div className="dashboard-grid"><section className="panel"><div className="panel-heading"><div><small className="kicker">{t("PRIORITY")}</small><h2>{t(admin?"Evaluation cycle":profile.role==="instructor"?"Your results at a glance":"Evaluations to complete")}</h2></div>{!admin&&profile.role!=="instructor"&&<button className="inline-link" onClick={()=>navigate("evaluations")}>{t("View all")} <ArrowRight size={14}/></button>}</div>
 {admin?<div className="cycle-box"><span className="cycle-symbol"><Activity size={26}/></span><div><h3>{assignments.length?"Evaluation workspace is active":"Start the first evaluation cycle"}</h3><p>{assignments.length?"Follow assignments and outstanding forms to keep the evaluation process moving.":"Create evaluator accounts, then assign instructors and courses to launch evaluations."}</p><div className="progress-meta"><span>{assignments.filter(a=>a.status==="submitted").length} of {assignments.length} submissions</span><b>{assignments.length?Math.round(assignments.filter(a=>a.status==="submitted").length/assignments.length*100):0}%</b></div><div className="track"><i style={{width:(assignments.length?assignments.filter(a=>a.status==="submitted").length/assignments.length*100:0)+"%"}}/></div><div className="cycle-actions"><Button onClick={()=>navigate("assignments")}>{t("Manage assignments")} <ArrowRight size={15}/></Button><button className="inline-link" onClick={onUser}>{t("Provision an account")} <Plus size={14}/></button></div></div></div>
 :profile.role==="instructor"?<><div className="score-summary"><div className="score-circle"><b>{final===null?"—":final.toFixed(1)}</b><small>/100</small></div><div><strong>{final===null?"Awaiting full evaluation":"Weighted performance score"}</strong><p>{final===null?"Your final score will appear once all four evaluation components have results.":"Your result combines all four evaluation perspectives."}</p></div></div><div className="component-list">{FORMS.map(f=>{const row=myRows.find(r=>r.form_type===f&&r.area===null);return <div key={f}><span>{f==="student"?"Students":f==="department_head"?"Department head":f==="peer"?"Peer":"Self-evaluation"} <small>{FORM_META[f].weight}%</small></span><b>{row?.weighted_score==null?"—":Number(row.weighted_score).toFixed(1)+"%"}</b></div>})}</div></>
 :busy?<div className="loading-inline"><LoaderCircle className="spin" size={18}/> {t("Loading evaluations…")}</div>:open.length?<div className="assignment-list">{open.slice(0,4).map(a=><button className="assignment-row" key={a.id} onClick={()=>start(a)}><span className="assignment-file"><FileText size={18}/></span><span className="assignment-details"><b>{a.course_title}</b><small>{a.course_code} · {a.instructor?.full_name||t("Instructor")} · {t(formLabel(a.form_type))}</small></span><span className="deadline">{a.due_date?t("Due")+" "+dateText(a.due_date):t("No deadline")} <ArrowRight size={15}/></span></button>)}</div>:<Empty icon={CheckCircle2} title="You’re all caught up" detail="There are no open evaluations assigned to your account right now."/>}
 </section><section className="panel weighting-panel"><div className="panel-heading"><div><small className="kicker">{t("THE AUPES MODEL")}</small><h2>{t("Scoring weights")}</h2></div><span className="heading-icon"><Award size={18}/></span></div><p className="muted">{t("Every evaluator perspective contributes once to the final result.")}</p><div className="weight-list">{FORMS.map(f=><div key={f} className="weight-list-row"><i className={"weight-dot dot-"+f}/><span>{f==="student"?"Students":f==="department_head"?"Department head":f==="peer"?"Peer":"Self-evaluation"}</span><b>{FORM_META[f].weight}%</b><div className="track"><i style={{width:FORM_META[f].weight+"%"}}/></div></div>)}</div><div className="scoring-note"><ShieldCheck size={17}/><span><b>{t("Fair by design")}</b><br/>{t("NA ratings are excluded. Missing components remain pending rather than counting as zero.")}</span></div></section></div>
 {admin&&<section className="panel"><div className="panel-heading"><div><small className="kicker">{t("PERFORMANCE INTELLIGENCE")}</small><h2>{t("Instructor score overview")}</h2></div><button className="inline-link" onClick={()=>navigate("results")}>{t("Full results")} <ArrowRight size={14}/></button></div>{aggregate.length?<div className="table-scroll"><table className="data-table"><thead><tr><th>{t("Instructor")}</th><th>{t("Student · 40%")}</th><th>{t("Head · 35%")}</th><th>{t("Peer · 15%")}</th><th>{t("Self · 10%")}</th><th>{t("Final / 100")}</th></tr></thead><tbody>{aggregate.slice(0,6).map(item=><tr key={item.id}><td><span className="table-person"><Avatar name={item.person?.full_name||t("Instructor")}/><span><b>{item.person?.full_name||t("Instructor")}</b><small>{item.person?.department||t("Department not set")}</small></span></span></td>{FORMS.map(f=>{const row=item.rows.find(r=>r.form_type===f&&r.area===null);return <td key={f}>{row?.weighted_score==null?"—":Number(row.weighted_score).toFixed(1)+"%"}</td>})}<td><span className={cx("score-tag",item.score===null?"pending":"ready")}>{item.score===null?"In progress":item.score.toFixed(1)+"%"}</span></td></tr>)}</tbody></table></div>:<Empty icon={ChartNoAxesCombined} title="No evaluation results yet" detail="Submitted forms will appear here as the evaluation cycle progresses."/>}</section>}
 {!admin&&<section className="panel"><div className="panel-heading"><div><small className="kicker">{t("RECENT ACTIVITY")}</small><h2>{t("Your evaluation history")}</h2></div>{profile.role!=="instructor"&&<button className="inline-link" onClick={()=>navigate("evaluations")}>{t("View history")} <ArrowRight size={14}/></button>}</div>{done.length?<div className="assignment-list">{done.slice(0,4).map(a=><div className="assignment-row" key={a.id}><span className="assignment-file complete"><CheckCircle2 size={18}/></span><span className="assignment-details"><b>{a.course_title}</b><small>{a.course_code} · {t(formLabel(a.form_type))}</small></span><span className="submitted"><Check size={14}/> {t("Submitted")} {dateText(a.submitted_at?.slice(0,10))}</span></div>)}</div>:<p className="muted">{t("Completed evaluations will appear here so you can track your contribution.")}</p>}</section>}
 </div>;
}

function EvaluationList({assignments,busy,start}:{assignments:Assignment[];busy:boolean;start:(a:Assignment)=>void}){
 const {t}=useAppSettings();const [query,setQuery]=useState("");const [statusFilter,setStatusFilter]=useState("all");
 const filtered=assignments.filter(a=>[a.course_title,a.course_code,a.instructor?.full_name,formLabel(a.form_type)].some(v=>v?.toLowerCase().includes(query.toLowerCase()))&&(statusFilter==="all"||a.status===statusFilter));
 return <div className="page-stack">
  <section className="page-title-row"><div><small className="kicker">{t("YOUR TASKS")}</small><h1>{t("My evaluations")}</h1><p>{t("Find your assigned forms, check deadlines and continue open evaluations.")}</p></div><span className="count-tag">{assignments.filter(a=>a.status==="open").length} {t("open")}</span></section>
  <div className="toolbar filter-toolbar"><label className="search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={t("Search courses or instructors…")}/></label><div className="table-filters"><select aria-label={t("Filter by evaluation status")} value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="all">{t("All statuses")}</option><option value="open">{t("Awaiting response")}</option><option value="submitted">{t("Submitted")}</option><option value="closed">{t("Closed")}</option></select></div><span className="toolbar-count">{filtered.length} {t("evaluations")}</span></div>
  {busy?<div className="loading-inline"><LoaderCircle className="spin" size={18}/> {t("Loading assignments…")}</div>:filtered.length?<div className="eval-grid">{filtered.map(a=><article className="eval-card workspace-eval-card" key={a.id}><div className="eval-card-top"><span className={"form-tag form-"+a.form_type}>{formCode(a.form_type)}</span><span className={"status-tag status-"+a.status}>{a.status==="open"?t("Awaiting response"):a.status==="submitted"?t("Submitted"):t("Closed")}</span></div><span className="course-monogram">{a.course_code.slice(0,2).toUpperCase()}</span><h3>{a.course_title}</h3><p className="course-code">{a.course_code} · {a.academic_year}</p><div className="eval-meta"><div><small>{t("Instructor")}</small><b>{a.instructor?.full_name||t("Assigned instructor")}</b></div><div><small>{t("Deadline")}</small><b>{dateText(a.due_date)}</b></div></div>{a.status==="open"?<Button onClick={()=>start(a)} className="full"><ClipboardCheck size={15}/>{t("Continue evaluation")} <ArrowRight size={15}/></Button>:<span className="submitted"><CheckCircle2 size={15}/>{a.status==="submitted"?t("Response recorded"):t("Assignment closed")}</span>}</article>)}</div>:<Empty icon={ClipboardCheck} title={t("No evaluations found")} detail={query||statusFilter!=="all"?t("Try a different search or filter."):t("New assignments will appear here when your department sets them up.")}/>}
 </div>;
}

function ResultsPage({summaries,people,profile,admin}:{summaries:SummaryRow[];people:Profile[];profile:Profile;admin:boolean}){const {t}=useAppSettings();
 const [selected,setSelected]=useState("all");const [aiSummary,setAiSummary]=useState("");const [aiBusy,setAiBusy]=useState(false);const [aiError,setAiError]=useState("");const visible=admin?summaries.filter(r=>selected==="all"||r.instructor_id===selected):summaries.filter(r=>r.instructor_id===profile.id);const ids=[...new Set(summaries.map(r=>r.instructor_id))];const forms=visible.filter(r=>r.area===null);const score=admin&&selected==="all"?null:finalWeightedScore(visible);const name=admin?(selected==="all"?t("All instructors"):people.find(p=>p.id===selected)?.full_name||t("Instructor")):profile.full_name;
 async function summarizeFeedback(){const feedback=visible.filter(r=>r.area===null).map(r=>({form:r.form_type,strengths:r.strengths,improvements:r.improvements,rating_reasons:r.rating_reasons})).filter(r=>r.strengths||r.improvements||r.rating_reasons);if(!feedback.length){setAiError(t("There is no written feedback to summarize yet."));setAiSummary("");return;}setAiBusy(true);setAiError("");setAiSummary("");try{const {data,error}=await supabase.functions.invoke("public-ai-assistant",{body:{task:"summarize_feedback",feedback:JSON.stringify({instructor:name,feedback})}});if(error)throw error;if(data?.error)throw new Error(String(data.error));if(typeof data?.answer!=="string"||!data.answer.trim())throw new Error(t("The AI summary is unavailable right now."));setAiSummary(data.answer.trim());}catch(err){setAiError(err instanceof Error?err.message:t("The AI summary is unavailable right now."));}finally{setAiBusy(false)}}
 return <div className="page-stack"><section className="page-title-row"><div><small className="kicker">{t("FORM E · SUMMARY SHEET")}</small><h1>{t("Performance results")}</h1><p>{t("Review weighted scores and focus-area averages. Student responses are shown only in aggregate.")}</p></div>{admin&&<label className="result-filter">{t("Instructor")}<select value={selected} onChange={e=>setSelected(e.target.value)}><option value="all">{t("All instructors")}</option>{people.filter(p=>p.role==="instructor").map(p=><option key={p.id} value={p.id}>{p.full_name}</option>)}</select></label>}</section>
 {admin&&selected==="all"?<section className="panel"><div className="panel-heading"><div><small className="kicker">{t("AGGREGATED OVERVIEW")}</small><h2>{t("Evaluation completion by instructor")}</h2></div></div>{ids.length?<div className="table-scroll"><table className="data-table"><thead><tr><th>{t("Instructor")}</th><th>{t("Students")}</th><th>{t("Department head")}</th><th>{t("Peer")}</th><th>{t("Self")}</th><th>{t("Final result")}</th></tr></thead><tbody>{ids.map(id=>{const rows=summaries.filter(r=>r.instructor_id===id);const p=people.find(x=>x.id===id);const final=finalWeightedScore(rows);return <tr key={id}><td><span className="table-person"><Avatar name={p?.full_name||t("Instructor")}/><span><b>{p?.full_name||t("Instructor")}</b><small>{p?.department||t("Department not set")}</small></span></span></td>{FORMS.map(f=><td key={f}><span className={cx("score-tag",rows.some(r=>r.form_type===f&&r.area===null)?"ready":"pending")}>{rows.some(r=>r.form_type===f&&r.area===null)?t("Received"):t("Pending")}</span></td>)}<td><b>{final===null?"—":final.toFixed(1)+"%"}</b></td></tr>})}</tbody></table></div>:<Empty icon={ChartNoAxesCombined} title={t("No results available")} detail={t("Summaries update as evaluation forms are submitted.")}/>}</section>
 :<><section className="result-hero"><div><small className="kicker">{t("PERFORMANCE SUMMARY")}</small><h2>{name}</h2><p>{t("Weighted overall result")}</p><strong className="result-number">{score===null?t("Awaiting results"):score.toFixed(2)+"%"}</strong><small>{score===null?t("All four evaluator components are needed for a final score."):t("Out of 100 · Form E scoring model")}</small></div><div className="result-components">{FORMS.map(f=>{const row=forms.find(r=>r.form_type===f);return <article key={f}><span>{t(f==="student"?"Student evaluation":f==="department_head"?"Department head":f==="peer"?"Peer":"Self-evaluation")}</span><b>{row?.weighted_score==null?"—":Number(row.weighted_score).toFixed(2)+"%"}</b><small>{FORM_META[f].weight}% {t("weight")}</small></article>})}</div></section>
 <section className="panel"><div className="panel-heading"><div><small className="kicker">{t("COMPETENCY BREAKDOWN")}</small><h2>{t("Focus area averages")}</h2></div><span className="scale-note">{t("Scale: 0–5 · NA excluded")}</span></div>{visible.filter(r=>r.area!==null).length?<div className="area-list">{visible.filter(r=>r.area!==null).map(row=><div className="area-row" key={row.instructor_id+row.form_type+row.area}><div><b>{row.area}</b><small>{t(FORM_META[row.form_type].label)}</small></div><div className="area-track"><i style={{width:Math.max(0,Math.min(100,Number(row.average_score||0)/5*100))+"%"}}/></div><strong>{row.average_score==null?"—":Number(row.average_score).toFixed(2)}</strong></div>)}</div>:<Empty icon={ChartNoAxesCombined} title={t("No category scores yet")} detail={t("Focus-area averages appear when valid ratings are submitted.")}/>}</section>
 <section className="panel ai-review-panel"><div className="ai-review-toolbar"><div><small className="kicker">{t("AI FEEDBACK REVIEW")}</small><h2>{t("Understand the feedback")}</h2><p>{t("Summarize written comments and the reasons behind ratings into themes and practical next steps.")}</p></div><Button onClick={()=>void summarizeFeedback()} disabled={aiBusy||admin&&selected==="all"}>{aiBusy?<LoaderCircle size={16} className="spin"/>:<Sparkles size={16}/>} {aiBusy?t("Reviewing…"):t("Summarize with AI")}</Button></div>{admin&&selected==="all"&&<p className="muted">{t("Choose one instructor above to generate a focused summary.")}</p>}{aiError&&<p className="notice notice-error">{aiError}</p>}{aiSummary&&<div className="ai-review-result" aria-live="polite">{aiSummary}</div>}</section>
 <section className="panel"><div className="panel-heading"><div><small className="kicker">{t("QUALITATIVE FEEDBACK")}</small><h2>{t("Strengths and improvement areas")}</h2></div></div><div className="feedback-results"><article><span className="feedback-icon positive"><CheckCircle2 size={18}/></span><h3>{t("Recognized strengths")}</h3>{forms.some(r=>r.strengths)?forms.filter(r=>r.strengths).map(r=><div className="feedback-result" key={r.form_type}><small>{FORM_META[r.form_type].label}</small><p>{r.strengths}</p></div>):<p className="muted">{t("No qualitative strengths have been submitted yet.")}</p>}</article><article><span className="feedback-icon improve"><Activity size={18}/></span><h3>{t("Areas to improve")}</h3>{forms.some(r=>r.improvements)?forms.filter(r=>r.improvements).map(r=><div className="feedback-result" key={r.form_type}><small>{FORM_META[r.form_type].label}</small><p>{r.improvements}</p></div>):<p className="muted">{t("No improvement suggestions have been submitted yet.")}</p>}</article></div></section></>}
 </div>;
}

function AccountsPage({people,busy,onCreate}:{people:Profile[];busy:boolean;onCreate:()=>void}){
 const {t}=useAppSettings();const [query,setQuery]=useState("");const [roleFilter,setRoleFilter]=useState("all");const [statusFilter,setStatusFilter]=useState("all");
 const roles=[...new Set(people.map(p=>p.role))].sort();
 const filtered=people.filter(p=>[p.full_name,p.email,p.department,p.college,roleLabel(p.role)].some(v=>v?.toLowerCase().includes(query.toLowerCase()))&&(roleFilter==="all"||p.role===roleFilter)&&(statusFilter==="all"||(statusFilter==="active"?p.is_active:!p.is_active)));
 return <div className="page-stack">
  <section className="page-title-row"><div><small className="kicker">{t("ACCESS & IDENTITY")}</small><h1>{t("Account management")}</h1><p>{t("Manage accounts by role and status, and provision access for university staff and students.")}</p></div><Button onClick={onCreate}><Plus size={16}/>{t("Create account")}</Button></section>
  <section className="panel workspace-table-panel"><div className="toolbar filter-toolbar">
   <label className="search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={t("Search name, email or department…")}/></label>
   <div className="table-filters"><select aria-label={t("Filter by role")} value={roleFilter} onChange={e=>setRoleFilter(e.target.value)}><option value="all">{t("All roles")}</option>{roles.map(role=><option key={role} value={role}>{t(roleLabel(role))}</option>)}</select><select aria-label={t("Filter by status")} value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="all">{t("All statuses")}</option><option value="active">{t("Active")}</option><option value="inactive">{t("Inactive")}</option></select></div>
   <span className="toolbar-count">{filtered.length} / {people.length} {t("accounts")}</span>
  </div><div className="table-scroll"><table className="data-table"><thead><tr><th>{t("Account")}</th><th>{t("Role")}</th><th>{t("Department")}</th><th>{t("College / school")}</th><th>{t("Status")}</th></tr></thead><tbody>{filtered.map(p=><tr key={p.id}><td><span className="table-person"><Avatar name={p.full_name}/><span><b>{p.full_name||t("Name not set")}</b><small>{p.email}</small></span></span></td><td><span className="role-tag">{t(roleLabel(p.role))}</span></td><td>{p.department||"—"}</td><td>{p.college||"—"}</td><td><span className={cx("status-tag",p.is_active?"status-active":"status-closed")}>{p.is_active?t("Active"):t("Inactive")}</span></td></tr>)}</tbody></table></div>
  {busy&&<div className="loading-inline"><LoaderCircle size={17} className="spin"/> {t("Loading accounts…")}</div>}
  {!filtered.length&&!busy&&<Empty icon={Users} title={t("No accounts found")} detail={query||roleFilter!=="all"||statusFilter!=="all"?t("Try changing your search or filters."):t("Create the first account to start the evaluation cycle.")}/>}
  </section>
 </div>;
}

function AssignmentsPage({assignments,busy,onCreate}:{assignments:Assignment[];busy:boolean;onCreate:()=>void}){
 const {t}=useAppSettings();const [query,setQuery]=useState("");const [statusFilter,setStatusFilter]=useState("all");
 const filtered=assignments.filter(a=>[a.course_title,a.course_code,a.instructor?.full_name,a.evaluator?.full_name,formLabel(a.form_type),a.academic_year].some(v=>v?.toLowerCase().includes(query.toLowerCase()))&&(statusFilter==="all"||a.status===statusFilter));
 const openCount=assignments.filter(a=>a.status==="open").length;const submittedCount=assignments.filter(a=>a.status==="submitted").length;
 return <div className="page-stack">
  <section className="page-title-row"><div><small className="kicker">{t("EVALUATION CYCLE")}</small><h1>{t("Evaluation assignments")}</h1><p>{t("Track every evaluation by course, participant, academic term and response status.")}</p></div><Button onClick={onCreate}><Plus size={16}/>{t("New assignment")}</Button></section>
  <div className="stats-grid compact-stats"><Stat label={t("Total assignments")} value={assignments.length} detail={t("All evaluation forms")} icon={ClipboardCheck}/><Stat label={t("Open")} value={openCount} detail={t("Awaiting response")} icon={Clock3} tone="gold"/><Stat label={t("Submitted")} value={submittedCount} detail={t("Response recorded")} icon={CheckCircle2} tone="blue"/><Stat label={t("Evaluators")} value={new Set(assignments.map(a=>a.evaluator_id)).size} detail={t("Assigned participants")} icon={Users} tone="purple"/></div>
  <section className="panel workspace-table-panel"><div className="panel-heading"><div><small className="kicker">{t("ASSIGNMENT REGISTER")}</small><h2>{t("All evaluation forms")}</h2></div><span className="toolbar-count">{filtered.length} / {assignments.length} {t("records")}</span></div>
   <div className="toolbar filter-toolbar assignment-toolbar"><label className="search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={t("Search course, instructor or evaluator…")}/></label><div className="table-filters"><select aria-label={t("Filter by assignment status")} value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="all">{t("All statuses")}</option><option value="open">{t("Open")}</option><option value="submitted">{t("Submitted")}</option><option value="closed">{t("Closed")}</option></select></div></div>
   <div className="table-scroll"><table className="data-table"><thead><tr><th>{t("Course / form")}</th><th>{t("Instructor")}</th><th>{t("Evaluator")}</th><th>{t("Term")}</th><th>{t("Due date")}</th><th>{t("Status")}</th></tr></thead><tbody>{filtered.map(a=><tr key={a.id}><td><b>{a.course_title}</b><small className="table-sub">{a.course_code} · {t(formLabel(a.form_type))}</small></td><td>{a.instructor?.full_name||"—"}</td><td>{a.evaluator?.full_name||"—"}<small className="table-sub">{a.evaluator?.role?t(roleLabel(a.evaluator.role)):""}</small></td><td>{a.academic_year}<small className="table-sub">{t("Semester")} {a.semester}{a.batch?" · "+t("Batch")+" "+a.batch:""}</small></td><td>{dateText(a.due_date)}</td><td><span className={cx("status-tag","status-"+a.status)}>{t(a.status==="open"?"Open":a.status==="submitted"?"Submitted":"Closed")}</span></td></tr>)}</tbody></table></div>
   {busy&&<div className="loading-inline"><LoaderCircle size={17} className="spin"/> {t("Loading assignments…")}</div>}
   {!filtered.length&&!busy&&<Empty icon={CalendarDays} title={t("No assignments found")} detail={query||statusFilter!=="all"?t("Try another search or status filter."):t("Create a first assignment to launch an evaluation cycle.")}/>}
  </section>
 </div>;
}

function CreateUserModal({session,onClose,onCreated}:{session:Session;onClose:()=>void;onCreated:(text:string)=>void}){const {t}=useAppSettings();
 const [name,setName]=useState("");const [email,setEmail]=useState("");const [password,setPassword]=useState("");const [role,setRole]=useState("instructor");const [department,setDepartment]=useState("");const [college,setCollege]=useState("");const [busy,setBusy]=useState(false);const [error,setError]=useState("");
 async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError("");try{const response=await fetch(SUPABASE_URL+"/functions/v1/admin-create-user",{method:"POST",headers:{Authorization:"Bearer "+session.access_token,apikey:SUPABASE_KEY,"Content-Type":"application/json"},body:JSON.stringify({full_name:name,email,password,role,department,college})});const result=await response.json();if(!response.ok)throw new Error(t(result.error||"Unable to create account."));onCreated(t("Account created for")+" "+email+". "+t("Share its temporary password securely."));}catch(err){setError(err instanceof Error?err.message:"Unable to create account.");}finally{setBusy(false);}}
 return <Modal title="Create university account" description="Provision a role-specific AUPES account." onClose={onClose}><form className="form-stack modal-form" onSubmit={submit}><div className="field-grid"><label>{t("Full name")}<input required minLength={2} value={name} onChange={e=>setName(e.target.value)} placeholder={t("Full name")}/></label><label>{t("Role")}<select value={role} onChange={e=>setRole(e.target.value)}>{ROLE_OPTIONS.map(r=><option key={r.value} value={r.value}>{t(r.label)}</option>)}</select></label></div><label>{t("University email")}<input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@university.edu.et"/></label><label>{t("Temporary password")}<input type="password" minLength={8} required autoComplete="new-password" value={password} onChange={e=>setPassword(e.target.value)} placeholder={t("At least 8 characters")}/></label><div className="field-grid"><label>{t("Department")}<input value={department} onChange={e=>setDepartment(e.target.value)} placeholder={t("Department name")}/></label><label>{t("College / school")}<input value={college} onChange={e=>setCollege(e.target.value)} placeholder={t("College name")}/></label></div><div className="modal-hint"><ShieldCheck size={16}/> {t("The server verifies administrator access. Passwords are handled by Supabase Auth and are not stored in AUPES tables.")}</div>{error&&<Notice notice={{type:"error",text:error}}/>}<div className="modal-actions"><Button variant="outline" onClick={onClose}>{t("Cancel")}</Button><Button type="submit" disabled={busy}>{busy?<LoaderCircle className="spin" size={16}/>:<Plus size={16}/>} Create account</Button></div></form></Modal>;
}
function CreateAssignmentModal({people,admin,onClose,onCreated}:{people:Profile[];admin:Profile;onClose:()=>void;onCreated:(text:string)=>void}){const {t}=useAppSettings();
 const [form,setForm]=useState<FormType>("student");const [evaluator,setEvaluator]=useState("");const [instructor,setInstructor]=useState("");const [course,setCourse]=useState("");const [code,setCode]=useState("");const [year,setYear]=useState("2026/2027");const [semester,setSemester]=useState("1");const [batch,setBatch]=useState("1");const [due,setDue]=useState("");const [busy,setBusy]=useState(false);const [error,setError]=useState("");
 const requiredRole=form==="student"?"student":form==="department_head"?"department_head":form==="peer"?"peer":"instructor";const evaluators=people.filter(p=>p.role===requiredRole&&p.is_active);const instructors=people.filter(p=>p.role==="instructor"&&p.is_active);
 useEffect(()=>{setEvaluator(form==="self"?instructor:"")},[form,instructor]);
 async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError("");try{const actualEvaluator=form==="self"?instructor:evaluator;if(!actualEvaluator||!instructor)throw new Error(t("Select both an evaluator and an instructor."));if(form==="self"&&actualEvaluator!==instructor)throw new Error(t("Self-evaluation must be assigned to the instructor."));const {error}=await supabase.from("evaluation_assignments").insert({evaluator_id:actualEvaluator,instructor_id:instructor,form_type:form,course_title:course.trim(),course_code:code.trim(),academic_year:year.trim(),semester:Number(semester),batch:form==="student"?Number(batch):null,due_date:due||null,created_by:admin.id});if(error)throw error;onCreated(t("Assignment created for")+" "+course+".");}catch(err){setError(err instanceof Error?err.message:"Unable to create assignment.");}finally{setBusy(false);}}
 return <Modal title="Assign an evaluation" description="Create a course-specific evaluation task for the right roles." onClose={onClose}><form onSubmit={submit} className="form-stack modal-form"><label>{t("Evaluation form")}<select value={form} onChange={e=>setForm(e.target.value as FormType)}>{FORMS.map(f=><option key={f} value={f}>{t(formLabel(f))} · {FORM_META[f].weight}%</option>)}</select></label><div className="field-grid"><label>{t("Instructor")}<select required value={instructor} onChange={e=>setInstructor(e.target.value)}><option value="">{t("Select instructor…")}</option>{instructors.map(p=><option key={p.id} value={p.id}>{p.full_name}{p.department?" · "+p.department:""}</option>)}</select></label><label>{t("Evaluator")}<select required disabled={form==="self"} value={form==="self"?instructor:evaluator} onChange={e=>setEvaluator(e.target.value)}><option value="">{t("Select evaluator…")}</option>{evaluators.map(p=><option key={p.id} value={p.id}>{p.full_name}{p.department?" · "+p.department:""}</option>)}</select></label></div>{!evaluators.length&&form!=="self"&&<Notice notice={{type:"info",text:t("No active")+" "+t(roleLabel(requiredRole)).toLowerCase()+" "+t("account exists yet. Create the account first.")}}/>}<div className="field-grid"><label>{t("Course title")}<input required value={course} onChange={e=>setCourse(e.target.value)} placeholder={t("Course title")}/></label><label>{t("Course code")}<input required value={code} onChange={e=>setCode(e.target.value)} placeholder={t("e.g. ECON 201")}/></label></div><div className="field-grid field-three"><label>{t("Academic year")}<input required value={year} onChange={e=>setYear(e.target.value)}/></label><label>{t("Semester")}<select value={semester} onChange={e=>setSemester(e.target.value)}><option value="1">{t("Semester I")}</option><option value="2">{t("Semester II")}</option></select></label>{form==="student"&&<label>{t("Batch")}<select value={batch} onChange={e=>setBatch(e.target.value)}>{[1,2,3,4,5].map(n=><option key={n} value={n}>Batch {n}</option>)}</select></label>}</div><label>Due date (optional)<input type="date" value={due} onChange={e=>setDue(e.target.value)}/></label>{error&&<Notice notice={{type:"error",text:error}}/>}<div className="modal-actions"><Button variant="outline" onClick={onClose}>{t("Cancel")}</Button><Button type="submit" disabled={busy||(!evaluators.length&&form!=="self")}>{busy?<LoaderCircle className="spin" size={16}/>:<Plus size={16}/>} Create assignment</Button></div></form></Modal>;
}

function normalizeRoute(){
 const raw=window.location.pathname.replace(/\/+$/,"")||"/";
 const aliases:Record<string,string>={"/about-us":"/about","/process":"/how-it-works","/evaluation-methodology":"/scoring","/terms":"/terms-of-use"};
 if(raw==="/workspace"||raw.startsWith("/workspace/"))return "/app"+raw;
 return aliases[raw]||raw;
}










function readStoredSetting<T extends string>(key:string,allowed:readonly T[],fallback:T):T{
 if(typeof window==="undefined")return fallback;
 try{const value=window.localStorage.getItem(key) as T|null;return value&&allowed.includes(value)?value:fallback;}catch{return fallback;}
}
export default function App(){
 const [theme,setTheme]=useState<ThemeMode>(()=>readStoredSetting("aupes-theme",["light","dark"] as const,"light"));
 const [language,setLanguage]=useState<LanguageCode>(()=>readStoredSetting("aupes-language",["en","am","om","ti","so"] as const,"en"));
 const t=(key:string)=>translate(language,key);
 useEffect(()=>{document.documentElement.dataset.theme=theme;document.documentElement.style.colorScheme=theme;try{window.localStorage.setItem("aupes-theme",theme)}catch{}},[theme]);
 useEffect(()=>{document.documentElement.lang=language;try{window.localStorage.setItem("aupes-language",language)}catch{}},[language]);
 const [session,setSession]=useState<Session|null>(null);const [profile,setProfile]=useState<Profile|null>(null);const [authLoading,setAuthLoading]=useState(true);const [profileLoading,setProfileLoading]=useState(false);const [profileError,setProfileError]=useState("");const [path,setPath]=useState(normalizeRoute);
 const navigate=(to:string)=>{if(window.location.pathname!==to)window.history.pushState({},"",to);setPath(to);window.scrollTo({top:0,behavior:"auto"});};
 useEffect(()=>{const current=window.location.pathname;if(current==="/workspace"||current.startsWith("/workspace/"))window.history.replaceState({},"","/app"+current);},[]);
 useEffect(()=>{const onPopState=()=>setPath(normalizeRoute());window.addEventListener("popstate",onPopState);return()=>window.removeEventListener("popstate",onPopState)},[]);
 useEffect(()=>{let alive=true;const {data:{subscription}}=supabase.auth.onAuthStateChange((_event,next)=>{if(!alive)return;setSession(next);setAuthLoading(false)});return()=>{alive=false;subscription.unsubscribe()}},[]);
 const sessionUserId=session?.user.id;useEffect(()=>{let alive=true;async function load(){if(!sessionUserId){setProfile(null);setProfileError("");setProfileLoading(false);return;}setProfileLoading(true);setProfileError("");try{const {data,error}=await supabase.from("profiles").select("id,full_name,email,role,department,college,is_active").eq("id",sessionUserId).maybeSingle();if(error)throw error;if(!data)throw new Error("Your profile has not been provisioned. Contact the AUPES administrator.");if(alive)setProfile(data as Profile);}catch(err){if(alive){setProfile(null);setProfileError(err instanceof Error?err.message:"Unable to load your account profile.");}}finally{if(alive)setProfileLoading(false)}}void load();return()=>{alive=false}},[sessionUserId]);
 const workspacePath=path.startsWith("/app/workspace")||path.startsWith("/workspace");
 useEffect(()=>{if(!authLoading&&session&&path==="/sign-in")navigate("/app/workspace");if(!authLoading&&!session&&workspacePath)navigate("/sign-in")},[session,path,authLoading,workspacePath]);
 if(authLoading)return <Loading label={t("Please wait…")}/>;
 if(workspacePath&&session&&profileLoading)return <Loading label={t("Please wait…")}/>;
 if(workspacePath&&session&&profile&&!profile.is_active)return <div className="loading-screen"><ShieldCheck size={29}/><h2>{t("Account paused")}</h2><p>{t("Your AUPES access is inactive. Contact the system administrator.")}</p><Button variant="outline" onClick={()=>void supabase.auth.signOut()}>{t("Sign out")}</Button></div>;
 if(workspacePath&&session&&profile)return <AppSettingsContext.Provider value={{theme,setTheme,language,setLanguage,t}}><AppShell session={session} profile={profile} onSignOut={()=>void supabase.auth.signOut()}/></AppSettingsContext.Provider>;
 if(workspacePath&&session&&profileError)return <div className="loading-screen"><ShieldCheck size={30}/><h2>{t("Workspace setup needed")}</h2><p>{t(profileError)}</p><Button variant="outline" onClick={()=>void supabase.auth.signOut()}>{t("Sign out")}</Button></div>;
 return <AppSettingsContext.Provider value={{theme,setTheme,language,setLanguage,t}}><PublicSite route={path} navigate={navigate}/></AppSettingsContext.Provider>;
}
